modes.detail:
// ============ 开放地址法和分离链接法的根本差别 ============
//
//   **开放地址法**：所有元素都存在**同一个数组**里，冲突了就另找空位
//   **分离链接法**：数组每格挂一条链表，冲突了就挂在链表上
//
// 所以开放地址法的数组必须**开得比元素多**（留出空位给探测），
// 而分离链接法的表长可以接近元素数。
//
// 反过来，开放地址法不需要任何指针和额外内存分配 —— 对缓存很友好，
// 实测往往比分离链接法快。这是个典型的"空间换时间 vs 时间换空间"的取舍。
//
// ============ 三种探测方式共用一套结构 ============
//
// 这一节的三种做法**只在"怎么算下一个位置"上不同**，其余完全一样：
//
//   线性探测：(h(k) + i) % TableSize
//   平方探测：(h(k) ± i²) % TableSize
//   双散列  ：(h(k) + i × h₂(k)) % TableSize
//
// 所以下面把它们写成三个查找函数，方便直接对比。
// 注意：**插入也靠查找** —— 先找到"该放的位置"，再填进去。
// 这也是散列实现的一个惯用手法：插入 = 查找 + 写入。

// 元素类型
typedef int ElementType;

// 下标类型
typedef int Index;

// 表的最大容量
#define MAXTABLESIZE 20000

// 格子的状态
typedef enum
{
// 从没放过
    Empty,
// 有元素
    Legitimate,
// 墓碑（删过东西）
    Deleted
} EntryType;

// 一个格子
typedef struct HashEntry Cell;
struct HashEntry
{
// 关键字
    ElementType Data;
// 状态
    EntryType Info;
};

// 散列表
typedef struct TblNode *HashTable;
struct TblNode
{
// 表长（素数）
    int TableSize;
// 格子数组
    Cell *Cells;
};

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 没找到
#define NOTFOUND (-1)

// 取不小于 N 的下一个素数（和 06-01 一样）
int NextPrime(int N)
{
// 循环用
    int i;
// 待检查
    int p;

    if (N <= 2)
    {
        return 2;
    }
    if (N <= 3)
    {
        return 3;
    }

// 先看 N 本身是不是素数（N 是偶数就先加一到奇数）
    p = (N % 2 != 0) ? N : N + 1;

// 往上找
// 上界要留足余量 —— 否则 p 一超界就直接返回非素数了。
    while (p <= MAXTABLESIZE)
    {
// 从 p/2 往下试除
        for (i = (int)(p / 2); i > 2; i--)
        {
            if (p % i == 0)
            {
                break;
            }
        }

// 除到 i == 2 都没找到因子，说明 p 是素数
        if (i == 2)
        {
            break;
        }

// 否则试下一个奇数
        p += 2;
    }

// 返回
    return p;
}
// 建一个空表
HashTable CreateTable(int TableSize)
{
// 表
    HashTable H;
// 循环用
    int i;

// 分配
    H = (HashTable)malloc(sizeof(struct TblNode));
// 表长取素数
    H->TableSize = NextPrime(TableSize);
// 分配格子
    H->Cells = (Cell *)malloc(H->TableSize * sizeof(Cell));

// 全部标成空
    for (i = 0; i < H->TableSize; i++)
    {
        H->Cells[i].Info = Empty;
        H->Cells[i].Data = 0;
    }

    return H;
}

// 释放
void DestroyTable(HashTable H)
{
    if (H == NULL)
    {
        return;
    }
    free(H->Cells);
    free(H);
}

