modes.detail:
// ============ 双散列为什么需要第二个函数 ============
//
// 双散列的探测序列是：
//
//     h(k) + i × h₂(k)      i = 0, 1, 2, ...
//
// 关键要求：**h₂(k) 不能是 0**。
//
// 如果 h₂(k) = 0，那整条探测序列全是 h(k)，原地打转，永远找不到空位。
//
// 所以第二个散列函数要保证结果落在 [1, TableSize-1] 范围内。
//
// 常见做法是：
//
//     h₂(k) = R - (k % R)      其中 R 是小于表长的素数
//
// 因为 k % R 落在 [0, R-1]，所以 R - (k % R) 落在 [1, R] —— 一定不为 0。
//
// ============ 为什么双散列效果最好 ============
//
// 线性探测的步长永远是 1，平方探测的步长是 1, 4, 9...（固定序列），
// 而双散列的步长**依赖关键字本身**：
//
//   关键字不同的人，走的路子也不同 → 不容易互相干扰
//
// 所以双散列最接近"随机探测"的理想效果，冲突最少。
// 代价是要多算一个散列函数。

// 主散列函数：除留余数法
Index Hash(ElementType Key, int TableSize)
{
    return Key % TableSize;
}

// 第二个散列函数，用于双散列
// 保证返回值落在 [1, TableSize-1]，绝不会是 0。
Index Hash2(ElementType Key, int TableSize)
{
// 取一个比表长小的素数
    int R = NextPrime(TableSize / 2);

// R - (k % R) 落在 [1, R]
    return R - (Key % R);
}

// 算装填因子
double LoadFactor(HashTable H)
{
// 循环用
    int i;
// 已用格数（含墓碑）
    int used = 0;

    for (i = 0; i < H->TableSize; i++)
    {
        if (H->Cells[i].Info != Empty)
        {
            used++;
        }
    }
    return (double)used / H->TableSize;
}

