// ============ 为什么插入能复用查找 ============
//
// 因为"找不到"和"该插哪儿"是同一件事：
//
//   查找时按探测序列往后走，走到 Empty 就停 —— 这时要么找到了，要么不存在
//   而这个停下来的空位，**正好就是插入该放的位置**
//
// 这两件事完全重合，所以很多教材干脆只写一个函数，
// 用"是否传入要插入的值"来区分查找和插入。
//
// 本课程分开写，是为了让两种操作的意图更清楚。
//
// ============ 墓碑可以复用 ============
//
// 插入时遇到 Deleted 的格子，可以直接占用它。
//
// 但要注意：**不能一遇到墓碑就插**，因为后面可能已经存在这个关键字了 ——
// 那样就插入了重复元素。
//
// 所以正确做法是记住"第一个遇到的墓碑位置"，继续往后找：
//
//   · 如果找到了相同关键字 → 说明已存在，什么都不做
//   · 如果遇到 Empty（说明肯定不存在）→ 插到**之前记的那个墓碑位置**
//
// 这个细节很容易漏。本模块为了简洁，采用"不处理重复插入"的简化版 ——
// 但你要知道正式实现该怎么做。

// 线性探测插入：成功返回插入位置，表满返回 -1
int InsertLinear(HashTable H, ElementType Key, int *probes)
{
// 起始位置
    Index CurrentPos = Hash(Key, H->TableSize);
// 当前位置
    Index NewPos = CurrentPos;
// 试了几次
    int i = 0;

// 找空位
// 一直往后试，直到遇到真正空的格子（墓碑也算可用）。
    while (H->Cells[NewPos].Info == Legitimate)
    {
// 已经存在就不重复插入
        if (H->Cells[NewPos].Data == Key)
        {
            *probes = i + 1;
            return NewPos;
        }

// 试下一格
        i++;
        NewPos = (CurrentPos + i) % H->TableSize;

// 绕了一整圈 → 表满
        if (i >= H->TableSize)
        {
            *probes = i;
            return NOTFOUND;
        }
    }

// 填进去
    H->Cells[NewPos].Data = Key;
    H->Cells[NewPos].Info = Legitimate;

// 记录探测次数
    *probes = i + 1;

// 返回位置
    return NewPos;
}

// 线性探测的删除：标成墓碑，不真的清空
// 直接标成 Empty 会把探测链断掉，后面的元素就找不到了。
Status DeleteLinear(HashTable H, ElementType Key)
{
// 探测次数（这里不关心，但还是得传个变量进去）
    int probes;
// 先找到它
    int pos = FindLinear(H, Key, &probes);

    if (pos < 0)
    {
        return ERROR;
    }

// 标成墓碑
    H->Cells[pos].Info = Deleted;

    return OK;
}

