// ============ 平方探测的探测序列 ============
//
//     h(k) + 1², h(k) - 1², h(k) + 2², h(k) - 2², ...
//     也就是 h(k)±1, h(k)±4, h(k)±9, h(k)±16, ...
//
// 一左一右地跳，跳的幅度越来越大。
//
// 为什么这样能缓解聚集？
//
// 因为线性探测的问题在于"**散列到相近位置的元素会走同一条路**"。
//
//   20 % 11 = 9  →  试 10
//   31 % 11 = 9  →  试 10、0
//   42 % 11 = 9  →  试 10、0、1
//
// 它们全都沿着 9→10→0→1 走。而平方探测是 9→10→8→1→6……，
// **跳开了**，不容易形成连续的块。
//
// ============ 但它换来了一个新问题：二次聚集 ============
//
// **散列到同一个位置**的元素，探测序列仍然完全相同。
//
// 也就是说"同一起点"的元素依然会挤在一起。这个现象叫
// **二次聚集（secondary clustering）**。
//
// 比一次聚集好一些，但没根治 —— 根治要靠双散列。
//
// ============ 更要紧的问题：表长有讲究 ============
//
// 线性探测一定能走遍全表（因为它一格一格试）。
// **平方探测不一定。**
//
// 如果表长是合数，±i² 可能只覆盖到一半的格子，**有些位置永远试不到**。
//
// 教科书结论：**表长为形如 4k+3 的素数时，平方探测能覆盖全表。**
//
// 比如 7、11、19、23、31…… 都是 4k+3 形式的素数。
// （7 = 4×1+3，11 = 4×2+3，19 = 4×4+3）
//
// 所以用平方探测时，表长不能只取"任意素数"，还得满足这个条件。
// 这是个很容易被忽略的细节 —— 表长选错了，插入会"凭空失败"。

// 平方探测查找：返回位置；没找到返回 -1
int FindQuadratic(HashTable H, ElementType Key, int *probes)
{
// 起始位置
    Index CurrentPos = Hash(Key, H->TableSize);
// 当前位置
    Index NewPos = CurrentPos;
// 当前试探的步数
    int i = 0;
// 正负方向
    int sign = 1;
// 偏移量
    int offset;

    while (H->Cells[NewPos].Info != Empty && H->Cells[NewPos].Data != Key)
    {
// 步数加一
        i++;

// 奇数步往右、偶数步往左，幅度是 i² 的变化
// 具体偏移：i=1 时 +1，i=2 时 -1，i=3 时 +2²=+4…… 这里用简化写法：
// 偏移量 = sign × ((i + 1) / 2)²
        offset = ((i + 1) / 2) * ((i + 1) / 2) * sign;
        sign = -sign;

// 算出新位置并调整到合法范围
        NewPos = (CurrentPos + offset) % H->TableSize;
        while (NewPos < 0)
        {
            NewPos += H->TableSize;
        }

// 试得太多就放弃
        if (i >= H->TableSize)
        {
            *probes = i;
            return NOTFOUND;
        }
    }

// 探测次数
    *probes = i + 1;

// 找到了
    if (H->Cells[NewPos].Info == Legitimate && H->Cells[NewPos].Data == Key)
    {
        return NewPos;
    }

    return NOTFOUND;
}

