// ============ 双散列的探测序列 ============
//
//     h(k) + i × h₂(k)        i = 0, 1, 2, ...
//
// 步长不是固定的 1（线性）也不是固定的 1,4,9（平方），
// 而是**由关键字自己算出来的 h₂(k)**。
//
// 举例：表长 11，h₂(k) = 7 - (k % 7)
//
//   关键字 20：h = 9，h₂ = 7 - (20%7) = 7 - 6 = 1
//             探测序列：9、10、0、1、2……
//   关键字 31：h = 9，h₂ = 7 - (31%7) = 7 - 3 = 4
//             探测序列：9、2、6、10、3……  ← 完全不同的路子
//
// 这就是关键：**散列到同一个起始位置的两个元素，走的序列也不同**。
// 所以既没有一次聚集、也没有二次聚集。
//
// ============ 代价 ============
//
//   ① 多算一次散列函数（多一次取模运算）
//   ② h₂(k) 必须保证不为 0，否则原地打转
//   ③ h₂(k) 最好与表长互质，这样序列才能覆盖全表
//
// 第三条的常见做法：**表长取素数，h₂(k) 的结果落在 [1, 表长-1]**。
// 因为素数表长与任何比它小的正整数都互质，序列必然能走遍全表。

// 双散列查找：返回位置；没找到返回 -1
int FindDouble(HashTable H, ElementType Key, int *probes)
{
// 起始位置
    Index CurrentPos = Hash(Key, H->TableSize);
// 当前位置
    Index NewPos = CurrentPos;
// 步长（由第二个散列函数决定）
    Index step = Hash2(Key, H->TableSize);
// 试了几次
    int i = 0;

    while (H->Cells[NewPos].Info != Empty && H->Cells[NewPos].Data != Key)
    {
// 走一步，步长是 step
        i++;
        NewPos = (CurrentPos + i * step) % H->TableSize;

// 试遍了就放弃
        if (i >= H->TableSize)
        {
            *probes = i;
            return NOTFOUND;
        }
    }

// 探测次数
    *probes = i + 1;

// 找到了
    if (H->Cells[NewPos].Info == Legitimate && H->Cells[NewPos].Data == Key)
    {
        return NewPos;
    }

    return NOTFOUND;
}

