// ============ 怎么对比才公平 ============
//
// 要用**同一批关键字、同一个表长**，分别用三种方式插入，
// 然后比较总探测次数和最大探测次数。
//
// 为了把差别放大，这里故意挑一批**散列位置很集中**的关键字。
// 如果关键字本来就散得很开，三种方式都只用探测一次，看不出区别。

// 用指定方式插入一批关键字，返回总探测次数
// method: 1=线性 2=平方 3=双散列
int InsertBatch(HashTable H, const ElementType keys[], int n, int method, int *maxProbes)
{
// 循环用
    int i;
// 本次探测次数
    int probes;
// 总探测次数
    int total = 0;
// 起始位置和步长
    Index CurrentPos, NewPos, step;
// 试了几次
    int k;

// 最大探测次数
    *maxProbes = 0;

    for (i = 0; i < n; i++)
    {
// 算出起点
        CurrentPos = Hash(keys[i], H->TableSize);
        NewPos = CurrentPos;
        step = (method == 3) ? Hash2(keys[i], H->TableSize) : 1;
        k = 0;

// 找空位
        while (H->Cells[NewPos].Info == Legitimate)
        {
            k++;
            if (method == 1)
            {
                NewPos = (CurrentPos + k) % H->TableSize;
            }
            else if (method == 2)
            {
                int offset = ((k + 1) / 2) * ((k + 1) / 2) * ((k % 2) ? 1 : -1);
                NewPos = (CurrentPos + offset) % H->TableSize;
                while (NewPos < 0)
                {
                    NewPos += H->TableSize;
                }
            }
            else
            {
                NewPos = (CurrentPos + k * step) % H->TableSize;
            }

            if (k >= H->TableSize)
            {
                break;
            }
        }

// 填进去
        H->Cells[NewPos].Data = keys[i];
        H->Cells[NewPos].Info = Legitimate;

// 统计
        probes = k + 1;
        total += probes;
        if (probes > *maxProbes)
        {
            *maxProbes = probes;
        }
    }

    return total;
}

// 主函数
int main(void)
{
// 故意挑一批散列位置集中的关键字
