    printf("  （会连成一片 —— 这就是「一次聚集」）\n\n");

// ===== 平方探测 =====
    H2 = CreateTable(9);
    total2 = InsertBatch(H2, keys, n, 2, &max2);
    printf("=== 平方探测 ===\n");
    PrintTable(H2);
