    printf("=== 查找测试（在线性探测的表里）===\n");
    for (i = 0; i < n; i++)
    {
        int pos = FindLinear(H1, keys[i], &probes);
        printf("  找 %d: 位置 %d，探测 %d 次\n", keys[i], pos, probes);
    }
    {
