        printf("  找 999（不存在）: %s，探测 %d 次\n",
               pos < 0 ? "没找到" : "找到了", probes);
    }
    printf("\n");

// ===== 删除与墓碑 =====
    printf("=== 删除测试 ===\n");
    printf("删除 31: %s\n", DeleteLinear(H1, 31) == OK ? "成功" : "失败");
    PrintTable(H1);
    printf("（31 的位置变成 X —— 墓碑，不是 Empty）\n");
    printf("再找 42: ");
    {
