#include <stdio.h>
#include <stdlib.h>

/* ======== [已给出] 模块 01 typedef ======== */

typedef int ElementType;

typedef int Index;

#define MAXTABLESIZE 20000

typedef enum
{
    Empty,
    Legitimate,
    Deleted
} EntryType;

typedef struct HashEntry Cell;
struct HashEntry
{
    ElementType Data;
    EntryType Info;
};

typedef struct TblNode *HashTable;
struct TblNode
{
    int TableSize;
    Cell *Cells;
};

#define OK 1
#define ERROR 0
typedef int Status;

#define NOTFOUND (-1)

int NextPrime(int N)
{
    int i;
    int p;

    if (N <= 2)
    {
        return 2;
    }
    if (N <= 3)
    {
        return 3;
    }

    p = (N % 2 != 0) ? N : N + 1;

    while (p <= MAXTABLESIZE)
    {
        for (i = (int)(p / 2); i > 2; i--)
        {
            if (p % i == 0)
            {
                break;
            }
        }

        if (i == 2)
        {
            break;
        }

        p += 2;
    }

    return p;
}
HashTable CreateTable(int TableSize)
{
    HashTable H;
    int i;

    H = (HashTable)malloc(sizeof(struct TblNode));
    H->TableSize = NextPrime(TableSize);
    H->Cells = (Cell *)malloc(H->TableSize * sizeof(Cell));

    for (i = 0; i < H->TableSize; i++)
    {
        H->Cells[i].Info = Empty;
        H->Cells[i].Data = 0;
    }

    return H;
}

void DestroyTable(HashTable H)
{
    if (H == NULL)
    {
        return;
    }
    free(H->Cells);
    free(H);
}

/* ======== [已给出] 模块 02 Hash ======== */

Index Hash(ElementType Key, int TableSize)
{
    return Key % TableSize;
}

Index Hash2(ElementType Key, int TableSize)
{
    int R = NextPrime(TableSize / 2);

    return R - (Key % R);
}

double LoadFactor(HashTable H)
{
    int i;
    int used = 0;

    for (i = 0; i < H->TableSize; i++)
    {
        if (H->Cells[i].Info != Empty)
        {
            used++;
        }
    }
    return (double)used / H->TableSize;
}

/* ======== [已给出] 模块 03 FindLinear ======== */

int FindLinear(HashTable H, ElementType Key, int *probes)
{
    Index CurrentPos = Hash(Key, H->TableSize);
    Index NewPos = CurrentPos;
    int i = 0;

    while (H->Cells[NewPos].Info != Empty && H->Cells[NewPos].Data != Key)
    {
        i++;
        NewPos = (CurrentPos + i) % H->TableSize;

        if (i >= H->TableSize)
        {
            *probes = i;
            return NOTFOUND;
        }
    }

    *probes = i + 1;

    if (H->Cells[NewPos].Info == Legitimate && H->Cells[NewPos].Data == Key)
    {
        return NewPos;
    }

    return NOTFOUND;
}

/* ======== [已给出] 模块 04 InsertLinear ======== */

int InsertLinear(HashTable H, ElementType Key, int *probes)
{
    Index CurrentPos = Hash(Key, H->TableSize);
    Index NewPos = CurrentPos;
    int i = 0;

    while (H->Cells[NewPos].Info == Legitimate)
    {
        if (H->Cells[NewPos].Data == Key)
        {
            *probes = i + 1;
            return NewPos;
        }

        i++;
        NewPos = (CurrentPos + i) % H->TableSize;

        if (i >= H->TableSize)
        {
            *probes = i;
            return NOTFOUND;
        }
    }

    H->Cells[NewPos].Data = Key;
    H->Cells[NewPos].Info = Legitimate;

    *probes = i + 1;

    return NewPos;
}

Status DeleteLinear(HashTable H, ElementType Key)
{
    int probes;
    int pos = FindLinear(H, Key, &probes);

    if (pos < 0)
    {
        return ERROR;
    }

    H->Cells[pos].Info = Deleted;

    return OK;
}

/* ======== [已给出] 模块 05 FindQuadratic ======== */

int FindQuadratic(HashTable H, ElementType Key, int *probes)
{
    Index CurrentPos = Hash(Key, H->TableSize);
    Index NewPos = CurrentPos;
    int i = 0;
    int sign = 1;
    int offset;

    while (H->Cells[NewPos].Info != Empty && H->Cells[NewPos].Data != Key)
    {
        i++;

        offset = ((i + 1) / 2) * ((i + 1) / 2) * sign;
        sign = -sign;

        NewPos = (CurrentPos + offset) % H->TableSize;
        while (NewPos < 0)
        {
            NewPos += H->TableSize;
        }

        if (i >= H->TableSize)
        {
            *probes = i;
            return NOTFOUND;
        }
    }

    *probes = i + 1;

    if (H->Cells[NewPos].Info == Legitimate && H->Cells[NewPos].Data == Key)
    {
        return NewPos;
    }

    return NOTFOUND;
}

/* ======== [已给出] 模块 06 FindDouble ======== */

int FindDouble(HashTable H, ElementType Key, int *probes)
{
    Index CurrentPos = Hash(Key, H->TableSize);
    Index NewPos = CurrentPos;
    Index step = Hash2(Key, H->TableSize);
    int i = 0;

    while (H->Cells[NewPos].Info != Empty && H->Cells[NewPos].Data != Key)
    {
        i++;
        NewPos = (CurrentPos + i * step) % H->TableSize;

        if (i >= H->TableSize)
        {
            *probes = i;
            return NOTFOUND;
        }
    }

    *probes = i + 1;

    if (H->Cells[NewPos].Info == Legitimate && H->Cells[NewPos].Data == Key)
    {
        return NewPos;
    }

    return NOTFOUND;
}

/* ======== [已给出] 模块 07 PrintTable ======== */

void PrintTable(HashTable H)
{
    int i;

    printf("下标: ");
    for (i = 0; i < H->TableSize; i++)
    {
        printf("%4d", i);
    }
    printf("\n内容: ");
    for (i = 0; i < H->TableSize; i++)
    {
        if (H->Cells[i].Info == Legitimate)
        {
            printf("%4d", H->Cells[i].Data);
        }
        else if (H->Cells[i].Info == Deleted)
        {
            printf("%4s", "X");
        }
        else
        {
            printf("%4s", "-");
        }
    }
    printf("\n");
}

